SELECT EXISTS(SELECT 1 FROM oa_contract contract WHERE contract.tenant_id = #{tenantId}
    AND contract.contract_id = #{contractId}
    AND )

SELECT term_id FROM oa_contract_fulfilment_term WHERE tenant_id = #{tenantId} AND contract_id = #{contractId}
    AND deleted = 0 AND term_id IN #{id}
FOR UPDATE

SELECT id FROM oa_contract_milestone WHERE tenant_id = #{tenantId} AND contract_id = #{contractId}
    AND deleted = 0 AND id IN #{id}
FOR UPDATE

SELECT id FROM oa_contract_payment_schedule WHERE tenant_id = #{tenantId} AND contract_id = #{contractId}
    AND deleted = 0 AND id IN #{id}
FOR UPDATE

mapper.update:
UPDATE oa_contract SET portal_term_ids = #{contract.portalTermIds}, portal_milestone_ids = #{contract.portalMilestoneIds},
    portal_payment_schedule_ids = #{contract.portalPaymentScheduleIds}, version = version + 1,
    update_by = #{contract.updateBy}, update_time = #{contract.updateTime}
WHERE tenant_id = #{contract.tenantId} AND contract_id = #{contract.contractId} AND deleted = 0 AND version = #{contract.version}
